import java.util.*;

class Solution {
    public void rotate(int[][] grid) {
        int n = grid.length;
        // step 1: transpose (only swap above the diagonal)
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int tmp = grid[i][j];
                grid[i][j] = grid[j][i];
                grid[j][i] = tmp;
            }
        }
        // step 2: reverse every row
        for (int i = 0; i < n; i++) {
            int left = 0, right = n - 1;
            while (left < right) {
                int tmp = grid[i][left];
                grid[i][left] = grid[i][right];
                grid[i][right] = tmp;
                left++;
                right--;
            }
        }
    }
}

